using System;
using Demo3D.Bench;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;

namespace Demo3D.Runtime.Bench
{
    /// <summary>The materials the bench uses, generated by ProjectSetup under Resources/Bench.</summary>
    public sealed class BenchAssets
    {
        public Material Unit, Ground, Glow, Overdraw;

        public static BenchAssets Load()
        {
            var a = new BenchAssets
            {
                Unit = Resources.Load<Material>("Bench/BenchUnit"),
                Ground = Resources.Load<Material>("Bench/BenchGround"),
                Glow = Resources.Load<Material>("Bench/BenchGlow"),
                Overdraw = Resources.Load<Material>("Bench/BenchOverdraw"),
            };
            if (a.Unit == null || a.Ground == null || a.Glow == null || a.Overdraw == null)
                throw new InvalidOperationException("bench: materials missing from Resources/Bench (run Tasks.Configure)");
            return a;
        }
    }

    /// <summary>
    /// The bench scene (benchmarks.md, Stress scenes): flat ground under a sun with soft shadows,
    /// default ambient, and post-processing (bloom, neutral tonemapping, color adjustments,
    /// vignette; SSAO arrives with TD9's post stack), seen through the game camera.
    /// </summary>
    public sealed class BenchRig
    {
        public Camera Camera;
        public Light Sun;
        public Transform Root;
        UniversalAdditionalCameraData _camData;
        UniversalRenderPipelineAsset _pipeline;

        public static BenchRig Create()
        {
            foreach (var c in UnityEngine.Object.FindObjectsByType<Camera>(FindObjectsInactive.Include)) UnityEngine.Object.Destroy(c.gameObject);
            foreach (var l in UnityEngine.Object.FindObjectsByType<Light>(FindObjectsInactive.Include)) UnityEngine.Object.Destroy(l.gameObject);
            var rig = new BenchRig();
            rig.Root = new GameObject("Bench").transform;
            rig._pipeline = GraphicsSettings.currentRenderPipeline as UniversalRenderPipelineAsset
                            ?? throw new InvalidOperationException("bench: URP is not the active pipeline");

            var camGo = new GameObject("BenchCamera");
            camGo.transform.SetParent(rig.Root, false);
            rig.Camera = camGo.AddComponent<Camera>();
            rig.Camera.fieldOfView = (float)CameraGeometry.VFovDeg;
            rig.Camera.nearClipPlane = 1f;
            rig.Camera.farClipPlane = 400f;
            rig.Camera.allowHDR = true;
            rig.Camera.allowMSAA = true;
            rig.Camera.tag = "MainCamera";
            rig._camData = camGo.AddComponent<UniversalAdditionalCameraData>();
            rig._camData.renderPostProcessing = true;
            rig._camData.renderShadows = true;

            var sunGo = new GameObject("Sun");
            sunGo.transform.SetParent(rig.Root, false);
            sunGo.transform.rotation = Quaternion.Euler(50, 30, 0);
            rig.Sun = sunGo.AddComponent<Light>();
            rig.Sun.type = LightType.Directional;
            rig.Sun.intensity = 1.2f;
            rig.Sun.color = new Color(1f, 0.96f, 0.88f);
            rig.Sun.shadows = LightShadows.Soft;
            RenderSettings.sun = rig.Sun;

            var volGo = new GameObject("Post");
            volGo.transform.SetParent(rig.Root, false);
            var vol = volGo.AddComponent<Volume>();
            vol.isGlobal = true;
            var profile = ScriptableObject.CreateInstance<VolumeProfile>();
            var bloom = profile.Add<Bloom>(true);
            bloom.intensity.Override(0.6f);
            bloom.threshold.Override(1f);
            var tone = profile.Add<Tonemapping>(true);
            tone.mode.Override(TonemappingMode.Neutral);
            var color = profile.Add<ColorAdjustments>(true);
            color.contrast.Override(8f);
            color.saturation.Override(5f);
            var vignette = profile.Add<Vignette>(true);
            vignette.intensity.Override(0.22f);
            vol.sharedProfile = profile;
            return rig;
        }

        /// <summary>Places the camera for a view width and fits the shadow distance to the view.</summary>
        public void SetViewWidth(double viewWidthM)
        {
            CameraGeometry.Position(viewWidthM, out var y, out var z);
            Camera.transform.position = new Vector3(0, (float)y, (float)z);
            Camera.transform.rotation = Quaternion.Euler((float)CameraGeometry.PitchDeg, 0, 0);
            var fp = CameraGeometry.GroundFootprint(viewWidthM);
            double far = 0;
            for (int i = 0; i < 4; i++)
            {
                double dx = fp[2 * i], dy = y, dz = fp[2 * i + 1] - z;
                far = Math.Max(far, Math.Sqrt(dx * dx + dy * dy + dz * dz));
            }
            _pipeline.shadowDistance = (float)(far + 5); // "fitted to the view"
        }

        /// <summary>msaa4, taa or none.</summary>
        public void SetAntiAliasing(string aa)
        {
            switch (aa)
            {
                case "msaa4":
                    _pipeline.msaaSampleCount = 4;
                    _camData.antialiasing = AntialiasingMode.None;
                    break;
                case "taa":
                    _pipeline.msaaSampleCount = 1; // URP's TAA needs MSAA off
                    _camData.antialiasing = AntialiasingMode.TemporalAntiAliasing;
                    break;
                case "none":
                    _pipeline.msaaSampleCount = 1;
                    _camData.antialiasing = AntialiasingMode.None;
                    break;
                default:
                    throw new ArgumentException($"bench: unknown aa '{aa}' (msaa4, taa, none)");
            }
        }
    }

    /// <summary>
    /// The overdraw counters (benchmarks.md, Measurements): a debug replacement render, off the
    /// camera, into a 2048² float target with a 1920×1080 viewport. Pass 0 counts every opaque
    /// fragment with no depth test (opaque depth complexity); pass 1 lays the opaque depth; pass 2
    /// counts transparent fragments that pass it. A mip chain averages the target on the GPU, and
    /// one texel is read back, so the counter costs no CPU time; its frames are excluded from
    /// timing anyway.
    /// </summary>
    public sealed class OverdrawCounter : IOverdrawSink, IDisposable
    {
        const int Size = 2048;
        static readonly int VpId = Shader.PropertyToID("_OverdrawVP");
        readonly RenderTexture _rt;
        readonly Material _mat;
        readonly CommandBuffer _cmd = new CommandBuffer { name = "Demo3D overdraw" };
        readonly int _width, _height, _lastMip;
        int _pass;

        public OverdrawCounter(Material mat, int width, int height)
        {
            _mat = mat;
            _width = Math.Min(width, Size);
            _height = Math.Min(height, Size);
            var desc = new RenderTextureDescriptor(Size, Size, RenderTextureFormat.RGFloat, 24)
            {
                useMipMap = true,
                autoGenerateMips = false,
                msaaSamples = 1,
            };
            _rt = new RenderTexture(desc) { name = "Demo3D overdraw" };
            _rt.Create();
            _lastMip = _rt.mipmapCount - 1;
        }

        /// <summary>Renders the counters for this frame; <paramref name="done"/> gets (opaque depth,
        /// transparent fragments per pixel) when the readback lands.</summary>
        public void Render(Camera cam, IBenchScene scene, Action<double, double> done)
        {
            _cmd.Clear();
            _cmd.SetRenderTarget(_rt, 0);
            _cmd.ClearRenderTarget(true, true, Color.clear);
            _cmd.SetViewport(new Rect(0, 0, _width, _height));
            var vp = GL.GetGPUProjectionMatrix(cam.projectionMatrix, true) * cam.worldToCameraMatrix;
            _cmd.SetGlobalMatrix(VpId, vp);
            for (_pass = 0; _pass < 3; _pass++) scene.DrawOverdraw(this);
            _cmd.GenerateMips(_rt);
            double scale = (double)Size * Size / ((double)_width * _height);
            _cmd.RequestAsyncReadback(_rt, _lastMip, TextureFormat.RGFloat, req =>
            {
                if (req.hasError) return;
                var px = req.GetData<float>();
                done(px[0] * scale, px[1] * scale);
            });
            Graphics.ExecuteCommandBuffer(_cmd);
        }

        public void Opaque(Mesh mesh, Matrix4x4 matrix)
        {
            if (_pass < 2) _cmd.DrawMesh(mesh, matrix, _mat, 0, _pass);
        }

        public void Opaque(Mesh mesh, Matrix4x4[] matrices, int count)
        {
            if (_pass < 2) _cmd.DrawMeshInstanced(mesh, 0, _mat, _pass, matrices, count);
        }

        public void Transparent(Mesh mesh, Matrix4x4[] matrices, int count)
        {
            if (_pass == 2) _cmd.DrawMeshInstanced(mesh, 0, _mat, 2, matrices, count);
        }

        public void Dispose()
        {
            _cmd.Release();
            _rt.Release();
        }
    }
}
